//! Production scene and hit-tree regression checks for music colour and sound pickers.
use std::{path::Path,collections::HashSet};
use serde_json::json;
use crate::{model::{Model,Page,Action},draw::Text,gpu::Gpu,views::{self,ViewState}};
pub fn run(m:&mut Model,text:&mut Text,gpu:&mut Gpu,out:&Path)->Result<Vec<String>,String>{
 let saved=(m.page,m.settings_tab,m.scroll,m.native_state.clone(),m.prefs.clone(),m.details,m.demo,m.snapshot.clone(),m.artwork.as_ref().and_then(|a|a.seed));let mut captures=vec![];
 m.page=Page::Music;m.scroll=0.;m.snapshot["isPlaying"]=json!(true);m.prefs.monet=true;m.native_state["settings"]["ControlCenterColorSource"]=json!("Content");
 for dark in [false,true]{m.prefs.dark=dark;for(label,seed)in [("magenta",0xff00ff),("red",0xff0000),("green",0x00ff00),("blue",0x0000ff)]{if let Some(a)=&mut m.artwork{a.seed=Some(seed);}let v=views::render(m,text,1200.,800.,&ViewState::default());let name=format!("restrained-{label}-{dark}.png");gpu.capture(&v.scene,1200,800,&out.join(&name))?;captures.push(name);}}
 for(label,bg,fg)in [("teal",0x1d2e33,0x41494c),("purple",0x7d2b85,0x514158),("light",0xe4d6e8,0xeeeeee)]{let mut scheme=m.scheme();scheme.primary_container=bg;scheme.on_primary_container=fg;for page in [Page::Home,Page::Music]{m.page=page;let base=views::render(m,text,900.,680.,&ViewState{color_scheme:Some(scheme),..Default::default()});let i=base.hits.iter().position(|h|matches!(&h.action,Action::Media("previous"))).ok_or("previous transport missing")?;let target=base.hits[i].rect;for state in 0..3{let v=views::render(m,text,900.,680.,&ViewState{color_scheme:Some(scheme),pointer:if state>0{(target.center().x,target.center().y)}else{(-1.,-1.)},pressed:if state==2{Some(i)}else{None},..Default::default()});let name=format!("transport-{label}-{}-{state}.png",if page==Page::Home{"home"}else{"music"});gpu.capture(&v.scene,900,680,&out.join(&name))?;captures.push(name);}}}
 m.page=Page::Settings;m.settings_tab=6;m.demo=false;m.details[..3].fill(false);m.native_state["settings"]["NotificationSoundPath"]=json!("C:/saved-custom.wav");m.native_state["settings"]["NotificationSoundSource"]=json!("Custom");m.native_state["settings"]["NotificationVolume"]=json!(17.);
 for dark in [false,true]{m.prefs.dark=dark;for(w,h)in [(900.,680.),(1200.,800.)]{m.scroll=0.;m.details[..3].fill(false);let v=views::render(m,text,w,h,&ViewState::default());if v.hits.iter().filter(|h|matches!(&h.action,Action::Details(i)if *i<3)&&h.rect.height()>=75.).count()!=3{return Err("collapsed sound categories must all fit the window".into())}if v.hits.iter().any(|h|matches!(&h.action,Action::NativeCommand("soundSelect",_))){return Err("collapsed sounds leaked their choice list".into())}let name=format!("sounds-collapsed-{dark}-{}.png",w as u32);gpu.capture(&v.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);
  m.dispatch(Action::Details(0));let mut kinds=HashSet::new();let mut previews=HashSet::new();let first=views::render(m,text,w,h,&ViewState::default());let max=first.max_scroll;let name=format!("sounds-expanded-{dark}-{}.png",w as u32);gpu.capture(&first.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);
  for scroll in (0..=(max as usize+100)).step_by(40){m.scroll=(scroll as f64).min(max);let v=views::render(m,text,w,h,&ViewState::default());for hit in &v.hits{match &hit.action{Action::NativeCommand("soundSelect",value)if value["source"]=="Builtin"=>{if hit.rect.height()>40.{kinds.insert(value["kind"].as_str().unwrap_or("").to_owned());}},Action::NativeCommand("soundPreview",value)if value["kind"].is_string()=>{if hit.enabled&&hit.rect.height()>30.{previews.insert(value["kind"].as_str().unwrap_or("").to_owned());}},_=>{}}}}
  if kinds.len()!=12||previews.len()!=12{return Err(format!("sound options/preview reachability: {}/{}",kinds.len(),previews.len()))}m.scroll=max;let v=views::render(m,text,w,h,&ViewState::default());let name=format!("sounds-bottom-{dark}-{}.png",w as u32);gpu.capture(&v.scene,w as u32,h as u32,&out.join(&name))?;captures.push(name);
  m.dispatch(Action::Details(1));if m.details[..3]!=[false,true,false]||m.scroll!=0.{return Err("sound accordion does not open exclusively".into())}m.dispatch(Action::Details(2));if m.details[..3]!=[false,false,true]{return Err("device sound accordion state failed".into())}
 }}
 for cue in dotisle_domain::sound_catalog::CUES{m.dispatch(Action::NativeCommand("soundSelect",json!({"category":"Notification","source":"Builtin","kind":cue.id})));if m.setting("NotificationSound")!=cue.id||m.details[..3].iter().any(|v|*v)||m.scroll!=0.{return Err("sound selection did not update and close the picker".into())}}
 if m.setting("NotificationSoundPath")!="C:/saved-custom.wav"||m.setting("NotificationVolume")!=17.{return Err("selecting a bundled sound erased custom data".into())}
 m.page=saved.0;m.settings_tab=saved.1;m.scroll=saved.2;m.native_state=saved.3;m.prefs=saved.4;m.details=saved.5;m.demo=saved.6;m.snapshot=saved.7;if let Some(a)=&mut m.artwork{a.seed=saved.8;}Ok(captures)
}
